  render: () => <div className="w-[420px] space-y-8 p-8 rounded-2xl border border-gray-100 bg-gradient-to-b from-white to-gray-50/50 shadow-sm">
      <div className="space-y-6">
        <h3 className="text-lg font-semibold text-gray-900">Input Sizes</h3>
        <div className="space-y-6">
          {(["xs", "sm", "md", "lg", "xl"] as const).map(size => <div key={size} className="space-y-2">
              <div className="text-sm font-medium text-gray-700">
                {size === "xs" && "Extra Small"}
                {size === "sm" && "Small"}
                {size === "md" && "Medium"}
                {size === "lg" && "Large"}
                {size === "xl" && "Extra Large"}
              </div>
              <div className="flex items-center gap-4">
                <Input size={size} placeholder="Type here..." className="flex-1" />
                <div className="text-xs text-gray-400 w-16 text-right">
                  {size === "xs" && "32px"}
                  {size === "sm" && "36px"}
                  {size === "md" && "40px"}
                  {size === "lg" && "44px"}
                  {size === "xl" && "48px"}
                </div>
              </div>
            </div>)}
        </div>
      </div>
    </div>
