  render: () => <div className="w-[420px] space-y-8 p-8 rounded-2xl border border-gray-100 bg-gradient-to-b from-white to-gray-50/50 shadow-sm">
      <div className="space-y-6">
        <h3 className="text-lg font-semibold text-gray-900">Input States</h3>
        <div className="space-y-5">
          <div className="space-y-2">
            <div className="text-sm font-medium text-gray-700">Default</div>
            <Input placeholder="Enter your information..." helperText="This is a regular input field" />
          </div>

          <div className="space-y-2">
            <div className="text-sm font-medium text-gray-700">Error State</div>
            <Input state="error" placeholder="Invalid input" helperText="Please enter a valid value" rightIcon={<AlertCircle className="h-4 w-4" />} />
          </div>

          <div className="space-y-2">
            <div className="text-sm font-medium text-gray-700">Disabled</div>
            <Input state="disabled" placeholder="Cannot interact with this field" helperText="This field is disabled" />
          </div>

          <div className="space-y-2">
            <div className="text-sm font-medium text-gray-700">Read Only</div>
            <Input state="readonly" value="Pre-filled information" helperText="This value is read-only" />
          </div>
        </div>
      </div>
    </div>
