  render: () => <div className="w-[420px] space-y-8 p-8 rounded-2xl border border-gray-100 bg-gradient-to-b from-white to-gray-50/50 shadow-sm">
      <div className="space-y-6">
        <h3 className="text-lg font-semibold text-gray-900">Icon Variants</h3>
        <div className="space-y-4">
          <Input label="Search" leftIcon={<Search className="h-4 w-4" />} placeholder="Search for anything..." helperText="Type to search" />

          <Input label="Email" leftIcon={<Mail className="h-4 w-4" />} rightIcon={<CheckCircle className="h-4 w-4 text-green-500" />} placeholder="name@example.com" helperText="Valid email format" />

          <Input label="Password" leftIcon={<Lock className="h-4 w-4" />} rightIcon={<EyeOff className="h-4 w-4 text-gray-400" />} type="password" placeholder="Enter password" helperText="At least 8 characters" />

          <Input label="Phone" leftIcon={<Phone className="h-4 w-4" />} placeholder="+1 (555) 123-4567" helperText="Include country code" />
        </div>
      </div>
    </div>
